import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"统一认证","description":"","frontmatter":{},"headers":[],"relativePath":"backend/authentication.md","filePath":"backend/authentication.md","lastUpdated":1794475115000}`),a={name:`backend/authentication.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="统一认证" tabindex="-1">统一认证 <a class="header-anchor" href="#统一认证" aria-label="Permalink to “统一认证”">​</a></h1><p>本页说明账号模型、令牌与会话、登录方式、锁屏与模仿登录，适用于后端开发者与接口对接方。</p><p>分工：框架只校验令牌（<code>Security.Jwt</code>，HS256）与判定策略；签发、刷新、会话、双因素、第三方登录、模仿与锁屏都是 Identity 包的操作与中间件。认证相关的配置都在 <code>BasicApp:Auth</code>，见<a href="./../configuration">配置参考</a>。</p><h2 id="账号模型" tabindex="-1">账号模型 <a class="header-anchor" href="#账号模型" aria-label="Permalink to “账号模型”">​</a></h2><p>账号是平台库实体 <code>SysUser</code>，不实现 <code>IMultiTenant</code>，以 <code>HomeTenantId</code> 记注册地租户（平台账号为 <code>platform</code>）。同一个登录名可以在不同租户各有一个账号；登录时填的 <code>tenant</code> 即注册地租户 ID，平台账号不填。账号还可以是别的租户的成员（<code>SysTenantMember</code>，含运维支持成员），登录后经切换租户进入。</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><code>Active</code></td><td>正常</td></tr><tr><td><code>Locked</code></td><td>管理员锁定（<code>users.lock</code>），由 <code>users.unlock</code> 解除；登录返回 <code>IDENTITY_DENIED_004</code></td></tr><tr><td><code>Disabled</code></td><td>管理员停用或本人停用，所有登录方式返回 <code>IDENTITY_DENIED_018</code></td></tr></tbody></table><p>连续登录失败另有锁定期（<code>SysUserSecurity.LockoutEndAt</code>），不改账号状态，到期自动解除，期间登录返回 <code>IDENTITY_DENIED_004</code> 并带剩余秒数。</p><p><strong>系统内置账号</strong>（<code>isSystemAccount</code>）：初始超级管理员与租户开通时的管理员。不能被停用、删除、锁定或由管理员重置密码，管理员也不能改它的邮箱与手机号；本人不能改用户名或关闭账号。一律返回 <code>IDENTITY_CONFLICT_014</code>。</p><p><strong>本人关闭账号</strong>：<code>profile.deactivate-account</code>（停用，管理员可以重新启用）与 <code>profile.delete-account</code>（注销，账号软删除）。都要当前密码，模仿会话不能做，租户所有者要先转移所有权（<code>IDENTITY_CONFLICT_011</code>），成功后吊销本人全部会话。</p><p><strong>密码</strong>：PBKDF2-SHA256 散列；至少 <code>PasswordMinLength</code>（8）位、同时含字母与数字；不能与最近 <code>PasswordHistoryDepth</code>（3）个密码相同。</p><h2 id="令牌与会话" tabindex="-1">令牌与会话 <a class="header-anchor" href="#令牌与会话" aria-label="Permalink to “令牌与会话”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>访问令牌</td><td>HS256 JWT，缺省 120 分钟（<code>AccessTokenMinutes</code>）；声明 <code>sub</code> 用户 ID、<code>tenant</code> 当前租户（平台没有）、<code>sid</code> 会话 ID、<code>role</code> 本会话激活的角色、模仿时 <code>act</code></td></tr><tr><td>刷新令牌</td><td>32 字节随机数，库里只存 SHA-256 散列，缺省 7 天（<code>RefreshTokenDays</code>）；每次刷新轮换、旧的立即失效，并顺延会话有效期；模仿会话的到期时间不顺延</td></tr><tr><td>会话</td><td><code>SysUserSession</code> 一行一个，ID 即 <code>sid</code>；记下浏览器、操作系统、设备类型、IP 与登录地点（IP 归属地）</td></tr><tr><td>会话门禁</td><td><code>SessionGateMiddleware</code> 在 Authenticate 阶段、框架 JWT 认证之后核对会话仍有效（结果缓存 <code>SessionCacheSeconds</code> 秒，缺省 30），已吊销、已过期或用户不正常即 <code>IDENTITY_DENIED_001</code>；不带 <code>sid</code> 的令牌不经门禁</td></tr></tbody></table><p>吊销会话的场景：注销、改密、管理员重置密码、找回密码、锁定或停用用户、删除用户、本人关闭账号、登录策略超限、强制下线、结束模仿、锁屏密码连错 5 次。吊销提交之后经 Realtime 推 <code>ForceLogout</code> 并断开这些会话的连接。</p><h2 id="登录方式" tabindex="-1">登录方式 <a class="header-anchor" href="#登录方式" aria-label="Permalink to “登录方式”">​</a></h2><p>开放哪些方式由系统参数 <code>identity.login-methods</code> 决定（方式名的 JSON 数组，如 <code>[&quot;password&quot;,&quot;passkey&quot;]</code>，可写 <code>password</code>、<code>email</code>、<code>phone</code>、<code>passkey</code>，只认平台的）：缺省 <code>[&quot;password&quot;]</code> 即只有密码登录，密码登录总是开着；不是字符串数组或有认不出的方式名即 <code>IDENTITY_VALIDATION_021</code>。<code>passkey</code> 还要宿主配了 <code>XiHan:Security:WebAuthn</code>，没配时列出也不算开放。<code>auth.login-config</code>（匿名 <code>GET</code>）把开放的方式、可用的第三方提供方、是否要图形验证码与是否开放注册返回给登录页。登录页取不到它时在表单上方常驻提示并可重试，取到之前「登录」不可点。</p><h3 id="密码登录-auth-login" tabindex="-1">密码登录 <code>auth.login</code> <a class="header-anchor" href="#密码登录-auth-login" aria-label="Permalink to “密码登录 auth.login”">​</a></h3><p>依次过三关：</p><ol><li>登录节流（<code>LoginThrottle</code>）：固定窗口只数失败，同一账号同一地址每个窗口 <code>LoginThrottleAccountLimit</code>（5）次、同一地址跨账号 <code>LoginThrottleIpLimit</code>（30）次，窗口 <code>LoginThrottleWindowSeconds</code>（60 秒）；超限 <code>IDENTITY_UNAVAILABLE_001</code> 并带 <code>retryAfter</code>。</li><li>图形验证码（<code>CaptchaEnabled</code>，缺省开）：<code>auth.captcha</code> 发一张 4 位数字的 SVG，共享缓存里只存散列，<code>CaptchaSeconds</code>（300 秒）内用一次即作废，错了是 <code>IDENTITY_VALIDATION_007</code>。</li><li>账号与密码：租户账号先核对租户存在、启用且没到期；连续失败达到 <code>MaxFailedAccessAttempts</code>（5）次锁定 <code>LockoutMinutes</code>（15）分钟。用户名错还是密码错不区分，都是 <code>IDENTITY_DENIED_003</code>。</li></ol><p>账号开了双因素即返回挑战（见<a href="#双因素">双因素</a>）；否则先过登录守卫（Access 实现：访问策略的登录时机、登录失败自动封禁），再开会话、签令牌对。</p><h3 id="强制修改由他人设置的密码" tabindex="-1">强制修改由他人设置的密码 <a class="header-anchor" href="#强制修改由他人设置的密码" aria-label="Permalink to “强制修改由他人设置的密码”">​</a></h3><p>密码由管理员创建或重置、由平台开通、由种子写入的账号都记着「密码由他人设置」，本人改密或找回密码后清除。系统参数 <code>identity.password</code>（JSON，只认平台的，缺省关）的 <code>forceChange</code> 决定要不要逼：</p><table tabindex="0"><thead><tr><th>状态</th><th>效果</th></tr></thead><tbody><tr><td>关（缺省）</td><td>只留着标记，直接放行</td></tr><tr><td>开</td><td>这些账号<strong>凭密码登录</strong>（含两步验证的第二步）时会话一开即锁定（令牌响应 <code>mustChangePassword</code> 为 <code>true</code>，锁定原因 <code>PasswordChangeRequired</code>），并发一条安全站内信提醒；打开之前已有的标记同样生效，已经在线的会话下次登录才受影响</td></tr></tbody></table><p>锁定中除 <code>profile.change-password</code> 与 <code>auth.logout</code> 外都是 <code>IDENTITY_DENIED_002</code>（<code>auth.refresh</code> 照常可用，新令牌还锁着）；前端弹改密表单，改完当场解开。验证码登录、第三方登录、通行密钥登录与模仿打开的会话不走这一步。参数写错即 <code>IDENTITY_VALIDATION_025</code>，只影响有标记的账号的密码登录。</p><h3 id="验证码登录-auth-send-login-code-→-auth-login-by-code" tabindex="-1">验证码登录 <code>auth.send-login-code</code> → <code>auth.login-by-code</code> <a class="header-anchor" href="#验证码登录-auth-send-login-code-→-auth-login-by-code" aria-label="Permalink to “验证码登录 auth.send-login-code → auth.login-by-code”">​</a></h3><p>方式要在 <code>identity.login-methods</code> 里开放。按邮箱（不分大小写）或已验证的手机号在登录租户里找账号；账号不存在、不唯一或停用时同样回答「已发送」，签发并计入限频，只是不发，不给探测账号的机会。</p><table tabindex="0"><thead><tr><th>限制</th><th>配置键（缺省）</th></tr></thead><tbody><tr><td>码的有效期</td><td><code>VerificationCodeMinutes</code>（10 分钟）</td></tr><tr><td>同一用途、同一目标两次发码的间隔</td><td><code>VerificationCodeIntervalSeconds</code>（60 秒）</td></tr><tr><td>每个目标每天（UTC）</td><td><code>VerificationCodeDailyPerTarget</code>（10 次）</td></tr><tr><td>每个客户端地址每天（UTC）</td><td><code>VerificationCodeDailyPerAddress</code>（50 次）</td></tr><tr><td>输错即作废</td><td><code>VerificationCodeMaxFailures</code>（5 次），之后锁定 <code>VerificationCodeLockoutMinutes</code>（10 分钟）</td></tr></tbody></table><p>这组限制对找回密码、个人中心验证联系方式与双因素的邮件 / 短信码同样适用。码对、发码之后联系方式没变才认账号，再核对状态与锁定期；账号开了双因素照样要第二步。</p><h3 id="第三方登录" tabindex="-1">第三方登录 <a class="header-anchor" href="#第三方登录" aria-label="Permalink to “第三方登录”">​</a></h3><p>GitHub、Gitee、Google、QQ、微信、企业微信、飞书、钉钉，配置在 <code>BasicApp:Auth:OAuth:Providers</code>，不分租户、不存库，启用且填了 <code>ClientId</code> 的才出现在登录页（见<a href="./../configuration">配置参考</a>）。</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>浏览器 → GET /api/oauth/{provider}/challenge  → 提供方授权页</span></span>
<span class="line"><span>       ← GET /api/oauth/{provider}/callback   回调不发令牌，只发一次性票据（5 分钟），重定向到前端回调页</span></span>
<span class="line"><span>前端回调页 → POST /api/auth:external-login（票据 + 注册地）→ 令牌</span></span></code></pre></div><ul><li>两个端点是普通端点、不经内核管道；发起时生成随机 <code>state</code> 存进共享缓存，同时种一枚 HttpOnly Cookie，回调时两者都对上才认（Google 另用 PKCE）。</li><li>只认已绑定的账号，不自动建号：没绑定即 <code>IDENTITY_DENIED_015</code>。先用账号密码登录，到个人中心「第三方绑定」由本人领绑定意图（<code>profile.begin-external-bind</code>，10 分钟、用一次），回调之后再由本人确认（<code>profile.link-external</code>）；<code>profile.external-logins</code> 列出、<code>profile.unlink-external</code> 解绑。</li><li>第三方登录同样过租户、账号状态、锁定期、登录守卫与双因素。</li></ul><h3 id="通行密钥-auth-begin-passkey-login-→-auth-login-by-passkey" tabindex="-1">通行密钥 <code>auth.begin-passkey-login</code> → <code>auth.login-by-passkey</code> <a class="header-anchor" href="#通行密钥-auth-begin-passkey-login-→-auth-login-by-passkey" aria-label="Permalink to “通行密钥 auth.begin-passkey-login → auth.login-by-passkey”">​</a></h3><p>用指纹、面容或设备密码代替密码登录。选项生成与响应核对用框架的 <code>Security.WebAuthn</code>：宿主在 <code>XiHan:Security:WebAuthn</code> 配了依赖方 ID（前端页面所在的域名，本地开发用 <code>localhost</code>）与来源（前端页面的地址）才装，再在 <code>identity.login-methods</code> 列出 <code>passkey</code> 才开放；没配即 <code>IDENTITY_UNAVAILABLE_007</code>，没开放即 <code>IDENTITY_DENIED_016</code>。通行密钥绑定在依赖方 ID 上，换了域名已登记的全部失效。</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>登录页 → POST /api/auth:begin-passkey-login           请求选项 + 一次性票据（不列允许的凭据，由认证器列出本站的通行密钥）</span></span>
<span class="line"><span>浏览器 navigator.credentials.get                     本人在设备上验证</span></span>
<span class="line"><span>登录页 → POST /api/auth:login-by-passkey（票据 + 断言）→ 令牌</span></span></code></pre></div><ul><li>不用填账号与注册地：按凭据 ID 找到登记的通行密钥，登录进它的注册地；没登记或已删除即 <code>IDENTITY_DENIED_022</code>。票据随选项的超时（缺省 300 秒）过期、只能用一次（<code>IDENTITY_VALIDATION_028</code>）。</li><li>框架核对来源、挑战、依赖方、用户在场与用户验证、签名、签名计数与凭据归属（断言必须带用户句柄，且等于这把凭据登记时的所属用户），失败是 <code>SECURITY_DENIED_005</code>（签名计数回退是 <code>SECURITY_DENIED_006</code>，可能是克隆的认证器），同时计入登录节流与登录守卫的认证失败。</li><li>同样过租户、账号状态、锁定期与登录守卫。认证器做了用户验证即顶替双因素；依赖方把 <code>UserVerification</code> 放宽到 <code>Preferred</code> 时，没做用户验证而账号开了双因素照样要第二步。</li><li>个人中心「安全设置」登记：<code>my-passkeys.begin-create</code> 先核对当前密码（错即 <code>IDENTITY_DENIED_003</code>），给创建选项与票据（列出已登记的凭据，同一认证器不重复登记）；浏览器创建之后 <code>my-passkeys.create</code> 连票据交回登记（票据只认发起的本人），成功后给本人发一条安全站内信。每人最多 10 个（<code>IDENTITY_CONFLICT_017</code>）。<code>my-passkeys.list</code> 列出、<code>my-passkeys.update</code> 改名、<code>my-passkeys.delete</code> 删除（删除后立即不能登录，设备上的那份要本人在设备上删）。登记、改名与删除模仿会话都不能做。</li><li>平台库只存公钥、签名计数、认证器型号与能否同步，不要求证明（<code>none</code>），私钥不离开认证器；用户句柄是用户 ID 的 16 个字节，不含个人信息。</li></ul><h3 id="双因素" tabindex="-1">双因素 <a class="header-anchor" href="#双因素" aria-label="Permalink to “双因素”">​</a></h3><p>方式有认证器（<code>Totp</code>）、邮箱（<code>Email</code>）与短信（<code>Phone</code>）。启用双因素的账号在第一步只得到挑战：</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;twoFactor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ticket&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;methods&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Totp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;codeSent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;expiresAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><ul><li><code>method</code> 只在唯一可用的方式是认证器时预先选定，否则为 <code>null</code>，由用户选。</li><li><code>auth.send-two-factor-code</code> 凭票据把码发到账号已验证的邮箱或手机号（认证器不发码），<code>auth.verify-two-factor</code> 凭票据与码换令牌；第二步重新核对账号状态、锁定期与租户。</li><li>票据有效期 <code>TwoFactorTicketMinutes</code>（10 分钟，从签发起算、不顺延），输错 <code>TwoFactorTicketMaxFailures</code>（5）次即作废、须重新登录（<code>IDENTITY_DENIED_008</code>）；码错同时计入账号的失败计数与登录节流。认证器的码按时间步防重放。</li><li>验证码登录的第二步不能用同一种渠道（<code>IDENTITY_DENIED_017</code>）。</li></ul><p>个人中心：<code>profile.setup-totp</code>（新密钥先加密暂存共享缓存 10 分钟）→ <code>profile.enable-two-factor</code>（用认证器的码确认才落库；邮箱与短信用 <code>profile.send-two-factor-code</code> 发的码确认）；<code>profile.disable-two-factor</code>（认证器要当前码，邮箱与短信要发到本人的码）。这几项模仿会话都不能做。不提供恢复码：丢了认证器由管理员 <code>users.reset-two-factor</code> 清掉（不能重置自己）。</p><h2 id="刷新、注销、切换" tabindex="-1">刷新、注销、切换 <a class="header-anchor" href="#刷新、注销、切换" aria-label="Permalink to “刷新、注销、切换”">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>auth.refresh</code></td><td>匿名，凭刷新令牌换新令牌对，刷新令牌轮换；会话已吊销或过期即 <code>IDENTITY_DENIED_001</code>，成员租户里的成员关系被移除或到期即 <code>IDENTITY_DENIED_006</code></td></tr><tr><td><code>auth.logout</code></td><td>吊销当前会话；模仿会话的发起人注销时一并吊销模仿会话</td></tr><tr><td><code>auth.switch-tenant</code></td><td>换到注册地租户、生效中的成员租户（含运维支持），平台账号还可回到平台：会话续用（同一 <code>sid</code>）、刷新令牌轮换、按新租户重算角色；先过目标一侧的登录守卫；模仿态不能切换</td></tr><tr><td><code>auth.activate-roles</code> / <code>auth.session-roles</code></td><td>换 / 查本会话激活的角色（动态职责分离，见<a href="./approval">约束规则与审批</a>）；<code>auth.session-roles</code> 在 Access 包</td></tr><tr><td><code>auth.me</code></td><td>当前用户、租户（含显示名）、会话、角色与模仿发起人</td></tr><tr><td><code>auth.permissions</code></td><td>Access 包：有效权限码、角色、按权限裁剪的菜单树与页面码</td></tr></tbody></table><h2 id="自助注册与找回密码" tabindex="-1">自助注册与找回密码 <a class="header-anchor" href="#自助注册与找回密码" aria-label="Permalink to “自助注册与找回密码”">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>auth.register</code></td><td>匿名，注册平台账号：要在配置里打开（<code>SelfRegistrationEnabled</code>，缺省关，否则 <code>IDENTITY_DENIED_020</code>）；开了图形验证码时同样先过验证码；登录名在平台一侧唯一，邮箱不能与平台一侧的正常账号重复（<code>IDENTITY_CONFLICT_013</code>）；注册后立即可用、不带任何角色，配好邮件且有 <code>auth-welcome</code> 模板时发一封欢迎邮件</td></tr><tr><td><code>auth.request-password-reset</code></td><td>匿名，租户须存在、启用且没到期；按邮箱或已验证的手机号发验证码（验证类模板，标题「重置密码」）；账号不存在、不唯一也回答已发送，签发并计入限频，只是不发</td></tr><tr><td><code>auth.reset-password</code></td><td>匿名，凭验证码设新密码：密码先按策略校验（不合格不消费验证码），码对、联系方式没变、账号正常才认；设好后清掉登录失败锁定，并吊销这个账号的全部会话</td></tr></tbody></table><p><code>auth.login-config</code> 带 <code>registrationEnabled</code>，登录页据此决定出不出注册入口；注册页要先勾选同意隐私政策与服务条款才提交，两份文书按界面语言放在前端 <code>packages/views/_core/authentication/legal/&lt;语言&gt;/</code>，部署方改主体、联系方式或条款时直接改对应语言的 Markdown；找回密码入口总在。要进租户的人先注册平台账号，再由租户加为成员。找回密码发验证码、不发链接，不依赖前端地址配置；平台模板里的 <code>auth-password-reset</code>（链接式）目前没有用到。</p><h2 id="锁屏" tabindex="-1">锁屏 <a class="header-anchor" href="#锁屏" aria-label="Permalink to “锁屏”">​</a></h2><p><code>auth.lock</code> 给当前会话记下锁屏密码的散列，之后这个会话除 <code>auth.unlock</code> 与 <code>auth.logout</code> 外都以 <code>IDENTITY_DENIED_002</code> 拒绝（<code>details.reason</code> 是 <code>ScreenLock</code>），只影响这一个端。解锁密码错一次是 <code>IDENTITY_DENIED_013</code>（带剩余次数），连错 5 次吊销会话（<code>IDENTITY_DENIED_014</code>）。强制改密的锁（<code>PasswordChangeRequired</code>）用不了锁屏密码（<code>IDENTITY_CONFLICT_006</code>），见<a href="#强制修改由他人设置的密码">强制修改由他人设置的密码</a>；锁屏的会话也不能靠改密解开。</p><h2 id="模仿登录" tabindex="-1">模仿登录 <a class="header-anchor" href="#模仿登录" aria-label="Permalink to “模仿登录”">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>impersonation.candidates</code></td><td>可模仿的用户，分页（<code>pageIndex</code> 从 1 起、<code>pageSize</code> 1–100），关键字匹配登录名与显示名</td></tr><tr><td><code>impersonation.start</code></td><td>以目标身份另开会话并签发令牌（<code>sub</code> 是目标、<code>act</code> 是发起人），不写目标的登录痕迹；发起人会话保留</td></tr><tr><td><code>impersonation.stop</code></td><td>自助操作：吊销模仿会话，在发起人原会话上轮换刷新令牌、签回本人的令牌；原会话已失效即要重新登录</td></tr></tbody></table><p>范围不填即发起人当前所在的上下文；租户主体只能在自己的租户里模仿；平台主体可指定租户（目标须是该租户的注册地用户或成员）或平台。不能模仿自己，不能在模仿态里再模仿；一条原会话同时只挂一条模仿会话，还没结束时再发起是 <code>IDENTITY_CONFLICT_015</code>（先 <code>impersonation.stop</code>，或等它到期）。权限码 <code>identity.impersonation.start</code>，开始与结束都进登录日志。</p><p><strong>权限上限</strong>：不能模仿超级管理员；除平台侧持 <code>*</code> 的超级管理员外，发起人不能模仿持 <code>*</code> 的账号，目标在目标上下文持有的权限码都要在发起人手里。</p><p><strong>模仿态拒绝的权限码</strong>：接管账号（重置密码、重置双因素、锁定、登录策略）、变更授权（角色的修改、授予、指派、继承，用户直授，用户数据范围，委托的新建、撤销与删除）、销毁数据（删除用户、角色、租户，初始化独立库）、OAuth 应用的修改（含重置客户端密钥）。持 <code>*</code> 也拦，<code>auth.permissions</code> 也不返回这些。</p><p>系统参数 <code>identity.impersonation</code>（JSON，按发起人所在的一侧取，租户可建同键参数覆盖，写错或越界即 <code>IDENTITY_VALIDATION_027</code>、不发起）：</p><table tabindex="0"><thead><tr><th>字段</th><th>缺省</th><th>说明</th></tr></thead><tbody><tr><td><code>sessionMinutes</code></td><td><code>30</code></td><td>模仿会话存活分钟数，1 到 480。从发起算起的硬期限：<code>auth.refresh</code> 只换令牌不顺延，访问令牌也不超过它；到期后 <code>IDENTITY_DENIED_001</code>，要接着用就重新发起</td></tr><tr><td><code>notifyTarget</code></td><td><code>true</code></td><td>发起时给被模仿者发一条安全站内信（落在模仿会话所在的一侧，按被模仿者的界面语言，不看通知偏好）；投递失败只记日志，不挡模仿</td></tr></tbody></table><h2 id="登录策略" tabindex="-1">登录策略 <a class="header-anchor" href="#登录策略" aria-label="Permalink to “登录策略”">​</a></h2><p>每个账号可以单独限制同时登录：<code>users.login-policy</code> 查看（<code>identity.users.read</code>），<code>users.set-login-policy</code> 设置（<code>identity.users.login-policy</code>），下次登录生效，已有会话不动。</p><table tabindex="0"><thead><tr><th>设置</th><th>登录时的效果</th></tr></thead><tbody><tr><td>不允许多端登录（<code>allowMultiLogin</code> 为 <code>false</code>）</td><td>只保留新会话，其余吊销</td></tr><tr><td>允许多端、<code>maxLoginDevices</code> 为 1 到 99</td><td>保留新会话和最近的几个，超过的吊销最早的</td></tr><tr><td>允许多端、<code>maxLoginDevices</code> 为 0（缺省）</td><td>不限</td></tr></tbody></table><p>模仿会话不算设备。被吊销的会话收到 <code>ForceLogout</code>。</p><h2 id="用户详情" tabindex="-1">用户详情 <a class="header-anchor" href="#用户详情" aria-label="Permalink to “用户详情”">​</a></h2><p><code>users.detail</code>（<code>GET /api/users/{id}:detail</code>，<code>identity.users.read</code>，可带 <code>timeZone</code> 按时区分天，缺省 UTC）给管理员看一个人的账号与活动，可见范围同 <code>users.get</code>：</p><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td><code>user</code></td><td>资料（字段安全同样套用）</td></tr><tr><td><code>security</code></td><td>邮箱与手机验证状态、双因素、是否锁定（管理员锁定或登录失败锁定期内）、锁定截止时间、连续失败次数；<a href="./multi-tenancy#外部成员">外部成员</a>为空，账号由其注册地维护</td></tr><tr><td><code>today</code></td><td>今日登录次数、访问次数、在线时长，只算当前一侧；平台看租户的用户时为空</td></tr><tr><td><code>currentSession</code></td><td>这一侧最近活动的会话（IP 遮掩，模仿会话不算）；没有有效会话时为空</td></tr></tbody></table><h2 id="在线用户与会话管理" tabindex="-1">在线用户与会话管理 <a class="header-anchor" href="#在线用户与会话管理" aria-label="Permalink to “在线用户与会话管理”">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>sessions.list</code></td><td><code>identity.sessions.read</code></td><td>一行一个有效会话：只看当前一侧，租户一侧按数据范围收窄，IP 遮掩，标出是否持有实时连接</td></tr><tr><td><code>sessions.summary</code></td><td><code>identity.sessions.read</code></td><td>有效会话数、有会话的用户数（同样按数据范围收窄）与持有实时连接的用户数</td></tr><tr><td><code>sessions.revoke</code></td><td><code>identity.sessions.revoke</code></td><td>批量吊销，可带给被下线用户看的原因；看不到的会话逐项 <code>IDENTITY_NOTFOUND_002</code>，调用方自己当前的会话逐项 <code>IDENTITY_CONFLICT_005</code></td></tr><tr><td><code>profile.sessions</code> / <code>profile.revoke-session</code> / <code>profile.revoke-other-sessions</code></td><td>登录即可</td><td>个人中心的「登录设备」：只按本人，不分侧、不套数据范围</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./permission">权限管理</a> · <a href="./access-policy">访问策略与权限条件</a> · <a href="./realtime">实时推送</a></li></ul>`,65)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};